"""Validate and package the opt-in memory-fix backend with upstream notices."""
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import subprocess

import pefile

ROOT = Path(__file__).resolve().parents[2]
UPSTREAM = "2b1a284f8453baa2bd193709b67e5183074c74ba"


def package(source, dll, output):
    if subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=source, text=True).strip() != UPSTREAM:
        raise ValueError("Unexpected DXVK source version")
    data = dll.read_bytes()
    pe = pefile.PE(data=data)
    if pe.FILE_HEADER.Machine != 0x8664:
        raise ValueError("Expected Windows x64 PE")
    exports = sorted(s.name.decode("ascii") for s in pe.DIRECTORY_ENTRY_EXPORT.symbols if s.name)
    if not {"Direct3DCreate9", "Direct3DCreate9Ex"}.issubset(exports):
        raise ValueError("Missing D3D9 exports")
    imports = sorted(e.dll.decode("ascii") for e in pe.DIRECTORY_ENTRY_IMPORT)
    if any(i.lower().startswith(("libgcc", "libstdc++", "libwinpthread")) for i in imports):
        raise ValueError("Backend requires an external compiler runtime")
    if b"bridge-mem1" not in data or b"BRIDGE_MEM_CHUNK" not in data:
        raise ValueError("Expected plainly marked experimental backend with allocator diagnostics")
    if output.exists():
        raise FileExistsError(f"Preserve the existing output: {output}")
    destination = output / "bin/.l4d2bridge/d3d9vk_x64.dll"
    destination.parent.mkdir(parents=True)
    shutil.copy2(dll, destination)
    shutil.copytree(ROOT / "licenses", output / "licenses")
    shutil.copy2(source / "LICENSE", output / "licenses/DXVK-LICENSE.txt")
    shutil.copy2(source / "include/openvr/LICENSE", output / "licenses/OpenVR-LICENSE.txt")
    vulkan_header = (source / "include/vulkan/include/vulkan/vulkan_core.h").read_text()
    notice_begin = vulkan_header.index("/*")
    notice_end = vulkan_header.index("*/", notice_begin) + 2
    (output / "licenses/Vulkan-Headers-COPYRIGHT.txt").write_text(vulkan_header[notice_begin:notice_end] + "\n")
    if not (output / "licenses/Vulkan-Headers-Apache-2.0.txt").is_file():
        raise ValueError("Missing full Apache 2.0 terms for Vulkan C headers")
    sha1_notice = (source / "src/util/sha1/sha1.c").read_text().split("#include", 1)[0]
    (output / "licenses/SHA1-NOTICE.txt").write_text(sha1_notice)
    dependencies = {
        "libdisplay-info": ("subprojects/libdisplay-info", "LICENSE"),
        "Vulkan-Headers": ("include/vulkan", "LICENSE.md"),
        "SPIRV-Headers": ("include/spirv", "LICENSE"),
        "MinGW-DirectX-Headers": ("include/native/directx", "COPYING.MinGW-w64.txt"),
    }
    sources = {"DXVK": {"url": "https://github.com/doitsujin/dxvk", "commit": UPSTREAM, "modified": True}}
    sources["OpenVR-Headers"] = {"url": "https://github.com/ValveSoftware/openvr", "path_in_dxvk": "include/openvr", "parent_commit": UPSTREAM, "license": "BSD-3-Clause"}
    sources["SHA1"] = {"author": "Steve Reid", "path_in_dxvk": "src/util/sha1", "parent_commit": UPSTREAM, "license": "Public Domain (upstream declaration)"}
    for name, (directory, notice) in dependencies.items():
        path = source / directory
        shutil.copy2(path / notice, output / "licenses" / f"{name}-LICENSE.txt")
        sources[name] = {
            "url": subprocess.check_output(["git", "remote", "get-url", "origin"], cwd=path, text=True).strip(),
            "commit": subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=path, text=True).strip(),
        }
    for pattern in ("gcc-mingw*/copyright", "g++-mingw*/copyright", "mingw-w64*/copyright"):
        for notice in Path("/usr/share/doc").glob(pattern):
            shutil.copy2(notice, output / "licenses" / f"toolchain-{notice.parent.name}.txt")
    common = Path("/usr/share/common-licenses")
    for name in ("GPL-3", "LGPL-2.1"):
        if (common / name).exists():
            shutil.copy2(common / name, output / "licenses" / f"toolchain-{name}.txt")
    for name in ("LICENSE", "THIRD_PARTY.md", "VERSION", "CHANGELOG.md"):
        shutil.copy2(ROOT / name, output / name)
    shutil.copy2(ROOT / "config/dxvk-memory-1.0.1.conf", output / "dxvk-memory-1.0.1.conf")
    guide = (ROOT / "docs/DXVK-MEMORY-EXPERIMENT.md").read_text()
    guide = guide.replace("(../LICENSE)", "(LICENSE)").replace("(../THIRD_PARTY.md)", "(THIRD_PARTY.md)").replace("(../CHANGELOG.md)", "(CHANGELOG.md)")
    (output / "DXVK-MEMORY-EXPERIMENT.md").write_text(guide, encoding="utf-8")
    (output / "docs").mkdir()
    shutil.copy2(ROOT / "docs/DXVK-MEMORY-EXPERIMENT.md", output / "docs/DXVK-MEMORY-EXPERIMENT.md")
    shutil.copy2(ROOT / "docs/PAGEBLOCK-DIAGNOSTICS.md", output / "docs/PAGEBLOCK-DIAGNOSTICS.md")
    shutil.copy2(ROOT / "docs/READBACK-RECOVERY-EXPERIMENT.md", output / "docs/READBACK-RECOVERY-EXPERIMENT.md")
    shutil.copy2(ROOT / "docs/LEARNED-RETENTION-EXPERIMENT.md", output / "docs/LEARNED-RETENTION-EXPERIMENT.md")
    (output / "patches").mkdir()
    shutil.copy2(ROOT / "patches/dxvk-memory-experiment.patch", output / "patches/dxvk-memory-experiment.patch")
    shutil.copytree(Path(__file__).parent, output / "source", ignore=shutil.ignore_patterns("__pycache__"))
    (output / "UPSTREAM-SOURCES.json").write_text(json.dumps(sources, indent=2) + "\n")
    (output / "PE-METADATA.json").write_text(json.dumps({"machine": "AMD64", "exports": exports, "imports": imports}, indent=2) + "\n")
    (output / "SHA256.json").write_text(json.dumps({"bin/.l4d2bridge/d3d9vk_x64.dll": hashlib.sha256(data).hexdigest()}, indent=2) + "\n")
    print(f"PASS: x64 D3D9 exports, modified-build markers, static compiler runtimes; {output}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--dll", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    package(args.source.resolve(), args.dll.resolve(), args.output.resolve())
